package ch.piiwii.mapsnavprobe;

import android.graphics.Bitmap;
import android.graphics.BitmapFactory;
import android.util.Base64;

/** Embedded idle artwork selected for the launcher widget. */
public final class IdleArtwork {
    private IdleArtwork() {}
    private static Bitmap cached;
    private static final String DATA =
            "";

    public static synchronized Bitmap get() {
        if (cached != null && !cached.isRecycled()) return cached;
        byte[] bytes = Base64.decode(DATA, Base64.DEFAULT);
        BitmapFactory.Options options = new BitmapFactory.Options();
        options.inPreferredConfig = Bitmap.Config.RGB_565;
        cached = BitmapFactory.decodeByteArray(bytes, 0, bytes.length, options);
        return cached;
    }
}
